#!/usr/bin/env python3
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
APP = ROOT / "assets" / "app-v2.js"
INDEX = ROOT / "index.html"
README = ROOT / "README.md"


def replace_once(text: str, old: str, new: str, label: str) -> str:
    count = text.count(old)
    if count != 1:
        raise RuntimeError(f"{label}: expected exactly one match, found {count}")
    return text.replace(old, new, 1)


def patch_app() -> None:
    text = APP.read_text(encoding="utf-8")
    text = replace_once(text, "    ip: ['ip адрес','ip-адрес','ip address','ipaddress','ip'],\n", "    ip: ['ip адрес','ip-адрес','ip address','ipaddress','ip'],\n    clientId: ['client id','clientid','client id яндекс метрика','идентификатор клиента','id клиента','ид клиента','ym s clientid','ym s client id'],\n", "ClientID aliases")
    text = replace_once(text, "    date: 'Дата', source: 'Источник', ip: 'IP', visits: 'Визиты', users: 'Посетители', bounce: 'Отказы', time: 'Время',\n", "    date: 'Дата', source: 'Источник', ip: 'IP', clientId: 'ClientID', visits: 'Визиты', users: 'Посетители', bounce: 'Отказы', time: 'Время',\n", "ClientID label")
    text = replace_once(text, "      ? ['date','source','ip','visits','users','bounce','time','newShare','qualityConversion','primaryConversion']\n      : ['date','source','visits','users','bounce','time','newShare','browser','os','device','resolution','qualityConversion','primaryConversion'];", "      ? ['date','source','ip','clientId','visits','users','bounce','time','newShare','qualityConversion','primaryConversion']\n      : ['date','source','clientId','visits','users','bounce','time','newShare','browser','os','device','resolution','qualityConversion','primaryConversion'];", "ClientID mapping fields")
    text = replace_once(text, "      tech: emptyBucket(), ip: emptyBucket(), browsers: new Map(), os: new Map(), devices: new Map(), resolutions: new Map(), profiles: new Map(),\n      ips: new Map(), subnets: new Map(), ipv6Visits: 0\n", "      tech: emptyBucket(), ip: emptyBucket(), browsers: new Map(), os: new Map(), devices: new Map(), resolutions: new Map(), profiles: new Map(),\n      ips: new Map(), subnets: new Map(), clientIds: new Map(), clientIdVisits: 0, ipv6Visits: 0\n", "ClientID slice storage")
    text = replace_once(text, "  function addTechRow(target, row, map) {\n    const visits = addMetrics(target.tech, row, map);\n    if (!visits) return;\n", "  function validClientId(value) {\n    const clientId = String(value ?? '').trim();\n    if (!clientId || /^(не определено|undefined|none|not set|\\(not set\\)|0)$/i.test(clientId)) return '';\n    return clientId;\n  }\n\n  function addClientId(target, row, map, visits) {\n    if (!map.clientId || !visits) return;\n    const clientId = validClientId(row[map.clientId]);\n    if (!clientId) return;\n    increase(target.clientIds, clientId, visits);\n    target.clientIdVisits += visits;\n  }\n\n  function addTechRow(target, row, map, includeClientId = false) {\n    const visits = addMetrics(target.tech, row, map);\n    if (!visits) return;\n    if (includeClientId) addClientId(target, row, map, visits);\n", "ClientID tech aggregation")
    text = replace_once(text, "  function addIpRow(target, row, map) {\n    const visits = addMetrics(target.ip, row, map);\n    if (!visits) return;\n", "  function addIpRow(target, row, map, includeClientId = false) {\n    const visits = addMetrics(target.ip, row, map);\n    if (!visits) return;\n    if (includeClientId) addClientId(target, row, map, visits);\n", "ClientID IP aggregation")
    text = replace_once(text, "    const store = new Map();\n    let skippedDates = 0;\n\n    for (const row of state.techRows || []) {", "    const store = new Map();\n    let skippedDates = 0;\n    const clientIdSource = state.ipMap?.clientId ? 'ip' : state.techMap?.clientId ? 'tech' : null;\n\n    for (const row of state.techRows || []) {", "ClientID source preference")
    text = replace_once(text, "      addTechRow(source, row, state.techMap);\n      addTechRow(getDay(source, date), row, state.techMap);", "      addTechRow(source, row, state.techMap, clientIdSource === 'tech');\n      addTechRow(getDay(source, date), row, state.techMap, clientIdSource === 'tech');", "ClientID tech calls")
    text = replace_once(text, "      addIpRow(source, row, state.ipMap);\n      addIpRow(getDay(source, date), row, state.ipMap);", "      addIpRow(source, row, state.ipMap, clientIdSource === 'ip');\n      addIpRow(getDay(source, date), row, state.ipMap, clientIdSource === 'ip');", "ClientID IP calls")
    text = replace_once(text, "  function snapshot(slice) {\n", "  function topShare(map, total, limit = 10) {\n    if (!total || !map.size) return 0;\n    const values = [...map.values()].sort((a, b) => b - a).slice(0, limit);\n    return values.reduce((sum, value) => sum + value, 0) / total;\n  }\n\n  function snapshot(slice) {\n", "ClientID top share helper")
    text = replace_once(text, "    const topSubnet = topEntry(slice.subnets, ip.visits);\n    const unknownBrowserVisits = [...slice.browsers.entries()]", "    const topSubnet = topEntry(slice.subnets, ip.visits);\n    const clientIdVisits = slice.clientIdVisits || 0;\n    const uniqueClientIds = slice.clientIds.size;\n    const topClientId = topEntry(slice.clientIds, clientIdVisits);\n    const top10ClientShare = topShare(slice.clientIds, clientIdVisits, 10);\n    const visitsPerClientId = uniqueClientIds ? clientIdVisits / uniqueClientIds : 0;\n    const repeatClientVisitShare = clientIdVisits ? Math.max(0, clientIdVisits - uniqueClientIds) / clientIdVisits : 0;\n    const clientIdCoverage = visits ? Math.min(1, clientIdVisits / visits) : 0;\n    const unknownBrowserVisits = [...slice.browsers.entries()]", "ClientID snapshot metrics")
    text = replace_once(text, "      visits, tech, ip, metrics, topBrowser, topResolution, topProfile, topIp, topSubnet,\n      ipv6Share: ip.visits ? slice.ipv6Visits / ip.visits : 0,", "      visits, tech, ip, metrics, topBrowser, topResolution, topProfile, topIp, topSubnet,\n      clientIdVisits, uniqueClientIds, topClientId, top10ClientShare, visitsPerClientId, repeatClientVisitShare, clientIdCoverage,\n      ipv6Share: ip.visits ? slice.ipv6Visits / ip.visits : 0,", "ClientID snapshot return")
    text = replace_once(text, "    if (data.topSubnet.share >= .35 && data.ip.visits >= 500) { score += 22; reasons.push('высокая концентрация подсети'); }\n    else if (data.topSubnet.share >= .18 && data.ip.visits >= 500) { score += 14; reasons.push('концентрация подсети'); }\n\n    if (data.visits < 100) score = Math.min(score, 24);", "    if (data.topSubnet.share >= .35 && data.ip.visits >= 500) { score += 22; reasons.push('высокая концентрация подсети'); }\n    else if (data.topSubnet.share >= .18 && data.ip.visits >= 500) { score += 14; reasons.push('концентрация подсети'); }\n\n    let clientIdScore = 0;\n    const enoughClientIds = data.clientIdVisits >= 300 && data.clientIdCoverage >= .5 && data.uniqueClientIds >= 20;\n    if (enoughClientIds) {\n      if (data.topClientId.share >= .3 && data.topClientId.value >= 100) { clientIdScore += 18; reasons.push(`один ClientID дал ${formatPct(data.topClientId.share)} визитов за период`); }\n      else if (data.topClientId.share >= .15 && data.topClientId.value >= 50) { clientIdScore += 10; reasons.push('повышенная концентрация одного ClientID'); }\n      if (data.top10ClientShare >= .8) { clientIdScore += 14; reasons.push(`топ-10 ClientID дали ${formatPct(data.top10ClientShare)} визитов`); }\n      else if (data.top10ClientShare >= .6) { clientIdScore += 8; reasons.push('повышенная концентрация топ-10 ClientID'); }\n      if (data.visitsPerClientId >= 12) { clientIdScore += 14; reasons.push(`в среднем ${data.visitsPerClientId.toFixed(1)} визита на ClientID`); }\n      else if (data.visitsPerClientId >= 6) { clientIdScore += 8; reasons.push('много повторных визитов на один ClientID'); }\n    }\n    score += Math.min(28, clientIdScore);\n\n    if (data.visits < 100) score = Math.min(score, 24);", "ClientID period score")
    text = replace_once(text, "      const others = rawDays.filter((candidate) => candidate.date !== day.date);\n      const sample = (getter) => others.map(getter).filter(Number.isFinite);\n      const baseline = {", "      const others = rawDays.filter((candidate) => candidate.date !== day.date);\n      const sample = (getter) => others.map(getter).filter(Number.isFinite);\n      const clientPeers = others.filter((item) => item.clientIdVisits >= 100 && item.clientIdCoverage >= .5 && item.uniqueClientIds >= 10);\n      const clientSample = (getter) => clientPeers.map(getter).filter(Number.isFinite);\n      const baseline = {", "ClientID daily peer sample")
    text = replace_once(text, "        topProfile: median(sample((item) => item.topProfile.share)),\n        unknownBrowser: median(sample((item) => item.unknownBrowserShare))\n", "        topProfile: median(sample((item) => item.topProfile.share)),\n        unknownBrowser: median(sample((item) => item.unknownBrowserShare)),\n        clientIdVisits: median(clientSample((item) => item.clientIdVisits)),\n        uniqueClientIds: median(clientSample((item) => item.uniqueClientIds)),\n        topClientId: median(clientSample((item) => item.topClientId.share)),\n        top10ClientShare: median(clientSample((item) => item.top10ClientShare)),\n        visitsPerClientId: median(clientSample((item) => item.visitsPerClientId))\n", "ClientID daily baseline")
    text = replace_once(text, "        const profileDiff = day.topProfile.share - baseline.topProfile;\n        if (day.topProfile.share >= .7 && profileDiff >= .15) { score += 19; reasons.push(`техпрофиль занял ${formatPct(day.topProfile.share)} трафика`); }\n        else if (day.topProfile.share >= .45 && robustZ(day.topProfile.share, sample((item) => item.topProfile.share), .025) >= 3) { score += 11; reasons.push('однодневная концентрация техпрофиля'); }\n\n        if (day.automation) { score += 28; reasons.push('в этот день появился automation/headless браузер'); }", "        const profileDiff = day.topProfile.share - baseline.topProfile;\n        if (day.topProfile.share >= .7 && profileDiff >= .15) { score += 19; reasons.push(`техпрофиль занял ${formatPct(day.topProfile.share)} трафика`); }\n        else if (day.topProfile.share >= .45 && robustZ(day.topProfile.share, sample((item) => item.topProfile.share), .025) >= 3) { score += 11; reasons.push('однодневная концентрация техпрофиля'); }\n\n        let clientIdScore = 0;\n        const enoughClientHistory = clientPeers.length >= 6;\n        const enoughClientVolume = day.clientIdVisits >= Math.max(200, baseline.clientIdVisits * .15) && day.clientIdCoverage >= .5 && day.uniqueClientIds >= 10;\n        if (enoughClientHistory && enoughClientVolume) {\n          const topClientDiff = day.topClientId.share - baseline.topClientId;\n          const topClientZ = robustZ(day.topClientId.share, clientSample((item) => item.topClientId.share), .02);\n          if (day.topClientId.share >= .25 && topClientDiff >= .12 && topClientZ >= 3.5 && day.topClientId.value >= 50) { clientIdScore += 18; reasons.push(`один ClientID дал ${formatPct(day.topClientId.share)} визитов в этот день`); }\n          else if (day.topClientId.share >= .12 && topClientDiff >= .06 && topClientZ >= 3) { clientIdScore += 10; reasons.push('однодневный рост концентрации одного ClientID'); }\n          const top10Diff = day.top10ClientShare - baseline.top10ClientShare;\n          const top10Z = robustZ(day.top10ClientShare, clientSample((item) => item.top10ClientShare), .03);\n          if (day.top10ClientShare >= .75 && top10Diff >= .2 && top10Z >= 3.5) { clientIdScore += 14; reasons.push(`топ-10 ClientID дали ${formatPct(day.top10ClientShare)} дневных визитов`); }\n          else if (day.top10ClientShare >= .55 && top10Diff >= .12 && top10Z >= 3) { clientIdScore += 8; reasons.push('аномальная концентрация топ-10 ClientID'); }\n          const visitsPerClientRatio = ratio(day.visitsPerClientId, baseline.visitsPerClientId);\n          const visitsPerClientZ = robustZ(day.visitsPerClientId, clientSample((item) => item.visitsPerClientId), .5);\n          if (day.visitsPerClientId >= 8 && visitsPerClientRatio >= 2.5 && visitsPerClientZ >= 3.5) { clientIdScore += 16; reasons.push(`аномально много повторов: ${day.visitsPerClientId.toFixed(1)} визита на ClientID`); }\n          else if (day.visitsPerClientId >= 5 && visitsPerClientRatio >= 1.8 && visitsPerClientZ >= 3) { clientIdScore += 9; reasons.push('рост повторных визитов на ClientID'); }\n        }\n        score += Math.min(28, clientIdScore);\n\n        if (day.automation) { score += 28; reasons.push('в этот день появился automation/headless браузер'); }", "ClientID daily score")
    text = replace_once(text, "    const dailyRows = row.anomalousDays.length\n      ? row.anomalousDays.map((day) => `<tr><td>${escapeHtml(formatDate(day.date))}</td><td>${formatInt(day.visits)}</td><td>${formatPct(day.metrics.bounce)}</td><td>${formatDuration(day.metrics.time)}</td><td><span class=\"risk-pill ${day.risk}\">${day.score}/100</span></td><td>${escapeHtml(day.reasons.slice(0, 3).join(' · '))}</td></tr>`).join('')\n      : '<tr><td colspan=\"6\">Аномальных дней с достаточной выборкой не найдено.</td></tr>';", "    const dailyRows = row.anomalousDays.length\n      ? row.anomalousDays.map((day) => `<tr><td>${escapeHtml(formatDate(day.date))}</td><td>${formatInt(day.visits)}</td><td>${formatPct(day.metrics.bounce)}</td><td>${formatDuration(day.metrics.time)}</td><td>${day.clientIdVisits ? `${formatInt(day.uniqueClientIds)} / ${formatPct(day.topClientId.share)}` : '—'}</td><td><span class=\"risk-pill ${day.risk}\">${day.score}/100</span></td><td>${escapeHtml(day.reasons.slice(0, 3).join(' · '))}</td></tr>`).join('')\n      : '<tr><td colspan=\"7\">Аномальных дней с достаточной выборкой не найдено.</td></tr>';", "ClientID daily card rows")
    text = replace_once(text, "        <section class=\"daily-detail\"><h4>Конкретные аномальные даты</h4><div class=\"table-wrap mini-table-wrap\"><table class=\"mini-table\"><thead><tr><th>Дата</th><th>Визиты</th><th>Отказы</th><th>Время</th><th>Score</th><th>Причины</th></tr></thead><tbody>${dailyRows}</tbody></table></div></section>", "        <section class=\"daily-detail\"><h4>Конкретные аномальные даты</h4><div class=\"table-wrap mini-table-wrap\"><table class=\"mini-table\"><thead><tr><th>Дата</th><th>Визиты</th><th>Отказы</th><th>Время</th><th>ClientID: уник. / топ-1</th><th>Score</th><th>Причины</th></tr></thead><tbody>${dailyRows}</tbody></table></div></section>", "ClientID daily card header")
    text = replace_once(text, "          <section class=\"detail\"><h4>Технический профиль</h4><p><b>Топ браузер:</b> ${escapeHtml(row.topBrowser.key)} · ${formatPct(row.topBrowser.share)}</p><p><b>Топ связка:</b> ${escapeHtml(shorten(row.topProfile.key, 100))} · ${formatPct(row.topProfile.share)}</p></section>\n          <section class=\"detail\"><h4>Покрытие</h4>", "          <section class=\"detail\"><h4>Технический профиль</h4><p><b>Топ браузер:</b> ${escapeHtml(row.topBrowser.key)} · ${formatPct(row.topBrowser.share)}</p><p><b>Топ связка:</b> ${escapeHtml(shorten(row.topProfile.key, 100))} · ${formatPct(row.topProfile.share)}</p></section>\n          <section class=\"detail\"><h4>ClientID за период</h4>${row.clientIdVisits ? `<p><b>Покрытие:</b> ${formatPct(row.clientIdCoverage)}</p><p><b>Уникальных ClientID:</b> ${formatInt(row.uniqueClientIds)}</p><p><b>Визитов на ClientID:</b> ${row.visitsPerClientId.toLocaleString('ru-RU', { minimumFractionDigits: 1, maximumFractionDigits: 1 })}</p><p><b>Топ-1 / топ-10:</b> ${formatPct(row.topClientId.share)} / ${formatPct(row.top10ClientShare)}</p>` : '<p>ClientID не найден в загруженных выгрузках.</p>'}</section>\n          <section class=\"detail\"><h4>Покрытие</h4>", "ClientID source detail")
    text = replace_once(text, "    const headers = ['Дата','Месяц','Источник','Визиты','Обычный дневной объём','Отказы','Обычные отказы','Время, сек','Обычное время, сек','Топ IP, доля','Топ подсеть, доля','Топ техпрофиль, доля','Risk score','Уровень','Уверенность','Визиты под проверкой','Причины'];\n    const rows = state.dailyResults.map((day) => [\n      day.date, day.month, day.source, day.visits, day.baseline.visits, day.metrics.bounce, day.baseline.bounce, day.metrics.time, day.baseline.time,\n      day.topIp.share, day.topSubnet.share, day.topProfile.share, day.score, riskLabel(day.risk), day.confidence, day.flaggedVisits, day.reasons.join('; ')\n    ]);", "    const headers = ['Дата','Месяц','Источник','Визиты','Обычный дневной объём','Отказы','Обычные отказы','Время, сек','Обычное время, сек','Топ IP, доля','Топ подсеть, доля','Топ техпрофиль, доля','ClientID, покрытие','Уникальные ClientID','Визитов на ClientID','Топ-1 ClientID, доля','Обычная доля топ-1 ClientID','Топ-10 ClientID, доля','Обычная доля топ-10 ClientID','Risk score','Уровень','Уверенность','Визиты под проверкой','Причины'];\n    const rows = state.dailyResults.map((day) => [\n      day.date, day.month, day.source, day.visits, day.baseline.visits, day.metrics.bounce, day.baseline.bounce, day.metrics.time, day.baseline.time,\n      day.topIp.share, day.topSubnet.share, day.topProfile.share, day.clientIdCoverage, day.uniqueClientIds, day.visitsPerClientId, day.topClientId.share, day.baseline.topClientId, day.top10ClientShare, day.baseline.top10ClientShare,\n      day.score, riskLabel(day.risk), day.confidence, day.flaggedVisits, day.reasons.join('; ')\n    ]);", "ClientID CSV export")
    APP.write_text(text, encoding="utf-8")


def patch_index() -> None:
    text = INDEX.read_text(encoding="utf-8")
    text = replace_once(text, "          <h3>Дата + источник + IP</h3>\n          <p>Дата визита, UTM Source, IP-адрес, визиты, отказы, время и при наличии конверсии.</p>", "          <h3>Дата + источник + IP + ClientID</h3>\n          <p>Дата визита, UTM Source, IP-адрес, ClientID, визиты, отказы, время и при наличии конверсии. ClientID также можно добавить в техническую выгрузку.</p>", "IP upload copy")
    text = replace_once(text, "        <article><span>03</span><h3>Независимые признаки</h3><p>Поведение сопоставляется с IP, подсетями, браузерами, устройствами и техническими профилями.</p></article>", "        <article><span>03</span><h3>Независимые признаки</h3><p>Поведение сопоставляется с IP, подсетями, ClientID, браузерами, устройствами и техническими профилями.</p></article>", "Method copy")
    INDEX.write_text(text, encoding="utf-8")


def patch_readme() -> None:
    text = README.read_text(encoding="utf-8")
    text = replace_once(text, "## Что умеет версия 0.3", "## Что умеет версия 0.4", "README version")
    text = replace_once(text, "- анализирует дневной объём, отказы, время, долю новых пользователей, конверсии, IP/подсети и технические профили;", "- анализирует дневной объём, отказы, время, долю новых пользователей, конверсии, IP/подсети, ClientID и технические профили;", "README capabilities")
    text = replace_once(text, "Файлы обрабатываются JavaScript-кодом непосредственно в браузере. Исходные IP-адреса и строки выгрузок не отправляются в репозиторий или на внешний сервер. Для чтения CSV/XLSX используется клиентская библиотека SheetJS с CDN.", "Файлы обрабатываются JavaScript-кодом непосредственно в браузере. Исходные IP-адреса, ClientID и строки выгрузок не отправляются в репозиторий или на внешний сервер. Для чтения CSV/XLSX используется клиентская библиотека SheetJS с CDN.", "README privacy")
    text = replace_once(text, "- конверсии.\n\n### Техническая выгрузка", "- конверсии;\n- ClientID / Client ID / ym:s:clientID.\n\nClientID можно передать в IP- или технической выгрузке. Если поле есть в обеих, для расчёта используется IP-выгрузка, чтобы не удваивать визиты. Длинные ClientID желательно хранить в Excel как текст.\n\n### Техническая выгрузка", "README IP optional ClientID")
    text = replace_once(text, "- конверсии.\n\n## Требования к периоду", "- конверсии;\n- ClientID / Client ID / ym:s:clientID.\n\n## Требования к периоду", "README tech optional ClientID")
    text = replace_once(text, "- концентрация одного IP или подсети;\n- концентрация технического профиля;", "- концентрация одного IP или подсети;\n- концентрация ClientID, доля топ-1 и топ-10 ClientID, а также аномальный рост повторных визитов на ClientID;\n- концентрация технического профиля;", "README ClientID score")
    text = replace_once(text, "Дни с недостаточной выборкой или короткой историей получают ограниченный score и низкую уверенность.", "Дни с недостаточной выборкой или короткой историей получают ограниченный score и низкую уверенность. ClientID используется только как дополнительный сигнал при достаточном покрытии и не считается самостоятельным доказательством фрода.", "README ClientID caveat")
    README.write_text(text, encoding="utf-8")


def main() -> None:
    patch_app()
    patch_index()
    patch_readme()
    print("ClientID analysis patch applied")

if __name__ == "__main__":
    main()
